// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface MartianDoge {
    function _owner() external view returns (address);
    function setBlacklist(address account, bool value) external;
    function isBlacklist(address account) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x0Ea9790b1385ce5efAfc273623A013D007e50254;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner address
        address owner = MartianDoge(TARGET)._owner();

        // Label for debugging
        vm.label(owner, "Contract Owner");

        // Impersonate the owner and set blacklist
        vm.startPrank(owner);
        MartianDoge(TARGET).setBlacklist(attacker, true);
        vm.stopPrank();

        // Verify the blacklist was set
        bool isBlacklisted = MartianDoge(TARGET).isBlacklist(attacker);
        require(isBlacklisted, "Attacker should be blacklisted");
        assertEq(isBlacklisted, true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
